    order_id = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(order_id)
    response = shop.fulfilment.handle_packing_slip(order_id)
    assert response.status == 409
    assert "error" in response.body


def test_low_stock_returns_active_products_strictly_below_threshold_sorted(shop):
    # shop stock: BOOK 50, LAMP 5, PEN 100
    response = shop.fulfilment.handle_low_stock(51)
    assert response.status == 200
    assert response.body == {"products": [
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
        {"sku": "BOOK", "name": "Book", "on_hand": 50},
    ]}


def test_low_stock_threshold_is_exclusive(shop):
    assert shop.fulfilment.handle_low_stock(5).body == {"products": []}
    assert shop.fulfilment.handle_low_stock(6).body == {
        "products": [{"sku": "LAMP", "name": "Lamp", "on_hand": 5}]}


def test_low_stock_ties_sorted_by_sku_and_skip_inactive_products(shop):
    shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 800, "on_hand": 5})
    shop.catalog.handle_add_product({"sku": "APP", "name": "Apple", "unit_price_cents": 50, "on_hand": 5})
    shop.catalog.handle_add_product({"sku": "ZZZ", "name": "Gone", "unit_price_cents": 50, "on_hand": 0})
    shop.catalog.handle_deactivate("ZZZ") if hasattr(shop.catalog, "handle_deactivate") else None
    skus = [p["sku"] for p in shop.fulfilment.handle_low_stock(10).body["products"]]
    assert skus == ["APP", "CUP", "LAMP"]


def test_low_stock_rejects_invalid_thresholds(shop):
    for bad in (-1, True, False, "5", 2.5, None):
        response = shop.fulfilment.handle_low_stock(bad)
        assert response.status == 400, bad
        assert "error" in response.body

