@dataclass(frozen=True)
class FulfilmentSummary:
    open_orders: int
    units_to_pick: int
    low_stock_products: int


# Warehouse low-stock line: products with fewer units than this on hand are low.
LOW_STOCK_LINE = 5


class FulfilmentService:
    def __init__(self, orders: OrderService, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def summary(self) -> FulfilmentSummary:
        """Open (not cancelled) orders, units across them, and active products below the low-stock line."""
        open_orders = [o for o in self._orders.list_all() if o.status != "cancelled"]
        units = sum(item.quantity for order in open_orders for item in order.items)
        low = len(self.low_stock(LOW_STOCK_LINE))
        return FulfilmentSummary(len(open_orders), units, low)

