    bad_requests = [
        {"sku": "", "quantity": 1},
        {"sku": 7, "quantity": 1},
        {"quantity": 1},
        {"sku": "BOOK", "quantity": 0},
        {"sku": "BOOK", "quantity": -2},
        {"sku": "BOOK", "quantity": True},
        {"sku": "BOOK", "quantity": 1.5},
        {"sku": "BOOK", "quantity": "3"},
        {"sku": "BOOK"},
    ]
    for bad in bad_requests:
        response = shop.fulfilment.handle_restock(bad)
        assert response.status == 400, bad
        assert "error" in response.body
    assert shop.catalog.handle_get("BOOK").body["on_hand"] == 50


def test_low_stock_rejects_invalid_thresholds(shop):
    for bad in (-1, True, False, "5", 2.5, None):
        response = shop.fulfilment.handle_low_stock(bad)
        assert response.status == 400, bad
        assert "error" in response.body
